const repos = $input.all().flatMap(i => Array.isArray(i.json.data) ? i.json.data : (i.json.full_name ? [i.json] : []));
return repos.filter(r => !r.archived && !r.disabled && r.default_branch)
  .map(r => ({ json: { full_name: r.full_name, default_branch: r.default_branch, private: r.private, html_url: r.html_url } }));

const repos = $('Keep Active Repos').all();
const now = new Date().toISOString();
return $input.all().map((it, i) => {
  const r = repos[i]?.json || {};
  const code = it.json.statusCode; const b = it.json.body || {};
  let status = 'FAIL', detail = '';
  if (code === 404) detail = 'No branch protection on default branch';
  else if (code === 403 || code === 401) { status = 'ERROR'; detail = 'Token cannot read protection (needs admin)'; }
  else if (code === 200) {
    const reviews = b.required_pull_request_reviews?.required_approving_review_count || 0;
    const issues = [];
    if (reviews < 1) issues.push('no required PR approvals');
    if (!b.enforce_admins?.enabled) issues.push('admins can bypass');
    if (b.allow_force_pushes?.enabled) issues.push('force pushes allowed');
    if (!b.required_status_checks) issues.push('no required status checks');
    status = issues.length === 0 ? 'PASS' : (reviews >= 1 ? 'PARTIAL' : 'FAIL');
    detail = issues.length ? issues.join('; ') : `${reviews} approval(s) required, admins enforced`;
  } else { status = 'ERROR'; detail = `HTTP ${code}`; }
  return { json: { check_id: 'GH-BRANCH-PROTECTION', system: 'GitHub', resource: `${r.full_name}@${r.default_branch}`,
    status, detail, evidence_ref: r.html_url, collected_at: now } };
});

const now = new Date().toISOString();
const users = $input.all().flatMap(i => i.json.users || []).filter(u => !u.suspended && !u.archived);
const out = [];
for (const u of users) {
  const ok = !!u.isEnrolledIn2Sv;
  out.push({ json: { check_id: 'GWS-2SV', system: 'Google Workspace', resource: u.primaryEmail,
    status: ok ? (u.isEnforcedIn2Sv ? 'PASS' : 'PARTIAL') : 'FAIL',
    detail: ok ? (u.isEnforcedIn2Sv ? '2SV enrolled and enforced' : '2SV enrolled but not enforced by policy') : '2-Step Verification NOT enrolled',
    evidence_ref: `directory/users/${u.id}`, collected_at: now } });
  if (u.isAdmin || u.isDelegatedAdmin) out.push({ json: { check_id: 'GWS-ADMIN-2SV', system: 'Google Workspace',
    resource: u.primaryEmail, status: ok ? 'PASS' : 'FAIL',
    detail: ok ? 'Admin has 2SV' : 'ADMIN account without 2SV', evidence_ref: `directory/users/${u.id}`, collected_at: now } });
}
return out;

const cfg = $('Set Audit Config').first().json;
const now = new Date().toISOString();
const row = (check_id, resource, status, detail) => ({ json: { check_id, system: 'AWS IAM', resource, status, detail,
  evidence_ref: `${cfg.aws_account_label}:credential-report`, collected_at: now } });
const xml = String($input.first().json.data || '');
const m = xml.match(/<Content>([\s\S]*?)<\/Content>/);
if (!m) return [row('AWS-CRED-REPORT', cfg.aws_account_label, 'ERROR', 'Credential report not returned. Increase the wait time or check IAM permissions.')];
const csv = Buffer.from(m[1].trim(), 'base64').toString('utf8').trim().split('\n');
const cols = csv[0].split(',');
const recs = csv.slice(1).map(r => { const v = r.split(','); return Object.fromEntries(cols.map((c, i) => [c, v[i]])); });
const age = s => (!s || ['N/A', 'no_information', 'not_supported'].includes(s)) ? null : Math.floor((Date.now() - new Date(s)) / 86400000);
const out = [];
for (const u of recs) {
  if (u.user === '<root_account>') {
    out.push(row('AWS-ROOT-MFA', 'root account', u.mfa_active === 'true' ? 'PASS' : 'FAIL', u.mfa_active === 'true' ? 'Root MFA enabled' : 'Root account has NO MFA'));
    const keys = u.access_key_1_active === 'true' || u.access_key_2_active === 'true';
    out.push(row('AWS-ROOT-KEYS', 'root account', keys ? 'FAIL' : 'PASS', keys ? 'Root access keys exist' : 'No root access keys'));
    continue;
  }
  if (u.password_enabled === 'true') out.push(row('AWS-USER-MFA', u.user, u.mfa_active === 'true' ? 'PASS' : 'FAIL',
    u.mfa_active === 'true' ? 'Console user has MFA' : 'Console user WITHOUT MFA'));
  for (const k of ['1', '2']) if (u[`access_key_${k}_active`] === 'true') {
    const a = age(u[`access_key_${k}_last_rotated`]);
    out.push(row('AWS-KEY-ROTATION', `${u.user} (key ${k})`, a !== null && a > cfg.key_rotation_days ? 'FAIL' : 'PASS', `Key age ${a ?? '?'} days`));
  }
  const used = [u.password_last_used, u.access_key_1_last_used_date, u.access_key_2_last_used_date].map(age).filter(x => x !== null);
  const idle = used.length ? Math.min(...used) : age(u.user_creation_time);
  out.push(row('AWS-STALE-USER', u.user, idle !== null && idle > cfg.stale_days ? 'FAIL' : 'PASS',
    used.length ? `Last activity ${idle} days ago` : `Never used, created ${idle} days ago`));
}
return out;

const period = $('Set Audit Config').first().json.period;
const CONTROLS = [
  { control_id: 'CTL-01', soc2: 'CC6.1', iso27001: 'A.5.17, A.8.5', title: 'MFA enforced for workforce and cloud identities', checks: ['GWS-2SV', 'AWS-USER-MFA'] },
  { control_id: 'CTL-02', soc2: 'CC6.1, CC6.3', iso27001: 'A.8.2', title: 'Privileged / root accounts hardened', checks: ['GWS-ADMIN-2SV', 'AWS-ROOT-MFA', 'AWS-ROOT-KEYS'] },
  { control_id: 'CTL-03', soc2: 'CC6.1', iso27001: 'A.5.17', title: 'Access keys rotated within policy', checks: ['AWS-KEY-ROTATION'] },
  { control_id: 'CTL-04', soc2: 'CC6.2, CC6.3', iso27001: 'A.5.18', title: 'Inactive accounts removed (access review)', checks: ['AWS-STALE-USER', 'AWS-CRED-REPORT'] },
  { control_id: 'CTL-05', soc2: 'CC8.1', iso27001: 'A.8.32, A.8.4', title: 'Peer-reviewed changes on protected branches', checks: ['GH-BRANCH-PROTECTION'] },
];
const evidence = $input.all().map(i => ({ ...i.json, period,
  control_ids: CONTROLS.filter(c => c.checks.includes(i.json.check_id)).map(c => c.control_id).join(', ') }));
const controls = CONTROLS.map(c => {
  const ev = evidence.filter(e => c.checks.includes(e.check_id));
  const passed = ev.filter(e => e.status === 'PASS').length;
  const failed = ev.filter(e => e.status === 'FAIL' || e.status === 'PARTIAL').length;
  const errors = ev.filter(e => e.status === 'ERROR').length;
  const status = !ev.length || errors === ev.length ? 'Evidence Missing'
    : failed === 0 && errors === 0 ? 'Compliant' : passed / ev.length >= 0.9 ? 'Partial' : 'Gap';
  return { control_id: c.control_id, soc2: c.soc2, iso27001: c.iso27001, title: c.title, status,
    passed, failed, errors, pass_rate: ev.length ? Math.round(passed / ev.length * 100) + '%' : 'n/a',
    top_failures: ev.filter(e => e.status !== 'PASS').slice(0, 8).map(e => `${e.resource}: ${e.detail}`).join(' | '),
    period, last_checked: new Date().toISOString() };
});
const total = evidence.length, pass = evidence.filter(e => e.status === 'PASS').length;
return [{ json: { period, generated_at: new Date().toISOString(), evidence, controls,
  stats: { total_checks: total, passed: pass, failed: total - pass, readiness_pct: total ? Math.round(pass / total * 100) : 0,
           controls_compliant: controls.filter(c => c.status === 'Compliant').length, controls_total: controls.length } } }];

return $input.first().json.evidence.map(e => ({ json: {
  period: e.period, check_id: e.check_id, control_ids: e.control_ids, system: e.system, resource: e.resource,
  status: e.status, detail: e.detail, evidence_ref: e.evidence_ref, collected_at: e.collected_at } }));

