const ai = $json.message?.content || {};
const m = $('Map Evidence to Controls').first().json;
const icon = s => s === 'Compliant' ? ':large_green_circle:' : s === 'Partial' ? ':large_yellow_circle:' : s === 'Gap' ? ':red_circle:' : ':white_circle:';
const ctl = m.controls.map(c => `${icon(c.status)} *${c.control_id}* ${c.title} (${c.soc2} · ${c.iso27001}): ${c.status} (${c.pass_rate})`).join('
');
const gaps = (ai.top_gaps || []).map(g => `• *${g.priority}* [${g.control_id}] ${g.issue}
   ↳ _${g.remediation}_ (owner: ${g.owner_team})`).join('
');
const text = `:shield: *SOC 2 / ISO 27001 evidence – ${m.period}*
` +
  `Readiness: *${ai.readiness_score ?? m.stats.readiness_pct}%* · Controls compliant: ${m.stats.controls_compliant}/${m.stats.controls_total} · Checks: ${m.stats.passed}/${m.stats.total_checks} passing

` +
  `${ai.executive_summary || ''}

*Control status*
${ctl}

*Prioritised gaps*
${gaps || 'None 🎉'}

_${ai.auditor_note || ''}_`;
return [{ json: { text } }];
